const clients = $input.first().json;
const options = clients.map(c => `<option value="${c.id}">${c.name} (${c.slug})</option>`).join('');

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>Nova - Synchronisation KB</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f5f5f5; display: flex; justify-content: center; align-items: center; min-height: 100vh; }
    .card { background: white; border-radius: 12px; padding: 32px; box-shadow: 0 4px 24px rgba(0,0,0,0.08); width: 100%; max-width: 480px; }
    h1 { font-size: 20px; color: #1a1a2e; margin-bottom: 4px; }
    .subtitle { color: #6b7280; font-size: 13px; margin-bottom: 24px; }
    label { display: block; font-size: 13px; font-weight: 600; color: #374151; margin-bottom: 6px; }
    select { width: 100%; padding: 10px 12px; border: 1px solid #d1d5db; border-radius: 8px; font-size: 14px; margin-bottom: 16px; background: white; }
    select:focus { outline: none; border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,0.1); }
    .checkbox-group { margin-bottom: 20px; }
    .checkbox-group label { display: flex; align-items: center; gap: 8px; font-weight: 400; cursor: pointer; }
    .checkbox-group input[type=checkbox] { width: 16px; height: 16px; accent-color: #3b82f6; }
    button { width: 100%; padding: 12px; background: #3b82f6; color: white; border: none; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; transition: background 0.2s; }
    button:hover { background: #2563eb; }
    button:disabled { background: #93c5fd; cursor: not-allowed; }
  </style>
</head>
<body>
  <div class="card">
    <h1>\u{1F680} Synchronisation Base de Connaissances</h1>
    <p class="subtitle">Importe le site web et les fichiers locaux vers la KB et le vector store</p>
    <form method="POST" action="/webhook/nova-sync-run">
      <label for="clientId">Client</label>
      <select name="clientId" id="clientId" required>
        <option value="" disabled selected>-- Choisir un client --</option>
        ${options}
      </select>

      <div class="checkbox-group">
        <label><input type="checkbox" name="webImport" value="true" checked> Import site web</label>
        <label><input type="checkbox" name="localImport" value="true" checked> Import fichiers locaux</label>
        <label><input type="checkbox" name="checkIndex" value="true" checked> V\u00e9rifier indexation</label>
      </div>

      <button type="submit">Lancer la synchronisation</button>
    </form>
  </div>
</body>
</html>`;

return [{ json: { html } }];

const body = $input.first().json.body || $input.first().json;
const clientId = body.clientId;
const webImport = body.webImport === 'true';
const localImport = body.localImport === 'true';
const checkIndex = body.checkIndex === 'true';

return [{ json: { clientId, webImport, localImport, checkIndex } }];

const input = $input.first().json;
const webResult = $('Web Import - Site').first()?.json || null;
const localResult = $('Local Import - Files').first()?.json || null;
const indexStatus = input;

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>Nova - R\u00e9sultat</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f5f5f5; display: flex; justify-content: center; align-items: center; min-height: 100vh; }
    .card { background: white; border-radius: 12px; padding: 32px; box-shadow: 0 4px 24px rgba(0,0,0,0.08); width: 100%; max-width: 560px; }
    h1 { font-size: 20px; color: #16a34a; margin-bottom: 16px; }
    .section { margin-bottom: 16px; padding: 12px; background: #f9fafb; border-radius: 8px; }
    .section h3 { font-size: 13px; color: #6b7280; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }
    .stat { display: flex; justify-content: space-between; padding: 4px 0; font-size: 14px; }
    .stat .label { color: #374151; }
    .stat .value { font-weight: 600; color: #1a1a2e; }
    a { display: inline-block; margin-top: 16px; padding: 10px 20px; background: #3b82f6; color: white; text-decoration: none; border-radius: 8px; font-size: 14px; font-weight: 600; }
    a:hover { background: #2563eb; }
  </style>
</head>
<body>
  <div class="card">
    <h1>\u2705 Synchronisation termin\u00e9e</h1>

    ${webResult ? `<div class="section"><h3>\u{1F310} Site Web</h3>
      <div class="stat"><span class="label">Chunks texte</span><span class="value">${webResult.textChunks || 0}</span></div>
      <div class="stat"><span class="label">Documents</span><span class="value">${webResult.docsStored || 0}</span></div>
      <div class="stat"><span class="label">Entr\u00e9es KB</span><span class="value">${webResult.kbEntries || 0}</span></div>
      <div class="stat"><span class="label">Doublons ignor\u00e9s</span><span class="value">${webResult.duplicatesSkipped || 0}</span></div>
    </div>` : ''}

    ${localResult ? `<div class="section"><h3>\u{1F4C1} Fichiers Locaux</h3>
      <div class="stat"><span class="label">Fichiers trait\u00e9s</span><span class="value">${localResult.filesProcessed || 0}</span></div>
      <div class="stat"><span class="label">Entr\u00e9es KB</span><span class="value">${localResult.kbEntries || 0}</span></div>
      <div class="stat"><span class="label">Chunks</span><span class="value">${localResult.chunks || 0}</span></div>
    </div>` : ''}

    ${indexStatus ? `<div class="section"><h3>\u{1F9E0} Indexation Vectorielle</h3>
      <div class="stat"><span class="label">Documents index\u00e9s</span><span class="value">${indexStatus.documents?.length || 0}</span></div>
      <div class="stat"><span class="label">Entr\u00e9es KB index\u00e9es</span><span class="value">${indexStatus.kbEntries?.length || 0}</span></div>
    </div>` : ''}

    <a href="/webhook/nova-sync">\u2190 Nouvelle synchronisation</a>
  </div>
</body>
</html>`;

return [{ json: { html } }];
